import {mountShell} from '../shared/shell.js?v=0.11.0';
import {escapeHtml,downloadText} from '../shared/utils.js?v=0.11.0';
import {attachCardDrag} from '../shared/drag.js?v=0.11.0';
import {uid,active,history,transition,undo,validateSession,portable,parse} from './state.js?v=0.11.0';
export const e=escapeHtml;
export const field=(id,label,value,attrs='',help='',rows=2)=>`<div class="field"><label for="${e(id)}">${label}</label>${help?`<p id="${e(id)}-help">${e(help)}</p>`:''}<textarea id="${e(id)}" rows="${rows}" maxlength="20000" ${attrs} ${help?`aria-describedby="${e(id)}-help"`:''}>${e(value)}</textarea></div>`;
export const select=(id,label,value,options,attrs='')=>`<div class="field"><label for="${e(id)}">${label}</label><select id="${e(id)}" ${attrs}>${Object.entries(options).map(([key,name])=>`<option value="${e(key)}" ${key===value?'selected':''}>${e(name)}</option>`).join('')}</select></div>`;
export const editAttrs=(collection,item,name)=>`data-field="${name}" data-item="${e(item)}" data-collection="${collection}"`;
export function boot(config){
  mountShell({active:config.route});const root=document.querySelector('#app'),dialog=document.querySelector('#dialog'),key=`thinking-lab:${config.route}:v1`;const first=config.make('first','example');let h=history({version:1,activeId:first.id,workspaces:[first]}),paused=false,recovery=null,timer,toastTimer,destroy,dialogOrigin;
  try{const raw=localStorage.getItem(key);if(raw)try{h=history(validateSession(JSON.parse(raw),config.validate));}catch{paused=true;recovery=raw;}}catch{}
  const kit={w:()=>active(h.present),state:()=>h.present,act,render,open,close:()=>dialog.close(),toast,uid};
  function toast(message){const el=document.querySelector('#notice');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
  function status(msg){const el=document.querySelector('#save-status');if(el)el.textContent=msg;}
  function save(now=false){clearTimeout(timer);if(paused)return;const run=()=>{try{localStorage.setItem(key,JSON.stringify(h.present));status('Saved in this browser');}catch{status('Saving unavailable · export a copy');}};if(now)run();else{status('Saving…');timer=setTimeout(run,220);}}
  function control(data){return data?[...root.querySelectorAll('[data-action]')].find(el=>Object.keys(data).every(k=>el.dataset[k]===data[k])):null;}
  function resize(scope=root){scope.querySelectorAll('textarea').forEach(el=>{el.style.height='auto';el.style.height=Math.min(el.id==='problem'?160:420,Math.max(el.scrollHeight,el.id==='problem'?45:75))+'px';});}
  function act(action,{repaint=true,group=null,checkpoint=true}={}){try{const focus=document.activeElement?.id,data=document.activeElement?.dataset?.action?{...document.activeElement.dataset}:null;if(checkpoint)h=transition(h,action,config,group);else{const next=transition(h,action,config);h={...h,present:next.present,group:null};}save();if(repaint){render();(focus?document.getElementById(focus):control(data))?.focus({preventScroll:true});}else{const b=root.querySelector('[data-action=undo]');if(b)b.disabled=!h.past.length;}return true;}catch(error){toast(error.message);return false;}}
  function render(){destroy?.();root.innerHTML=`<header class="page-top"><div><p class="eyebrow">${e(config.code)} / THINKING SCAFFOLD</p><h1>${e(config.title)}</h1><p class="lede">${e(config.description)}</p></div><div class="toolbar"><button data-action="undo" ${!h.past.length?'disabled':''}>↶ Undo</button><button data-action="workspaces">My work <span>${h.present.workspaces.length}</span></button><button data-action="export">Export ↓</button></div></header>${paused?`<div class="save-warning">${recovery?'Saved work needs recovery. Export it before starting again.':'Another tab changed saved work. Saving here is paused.'}<button data-action="recover">${recovery?'Download recovery copy':'Save this tab instead'}</button></div>`:''}<section class="problem-box"><div><label for="problem">${e(config.problemLabel||'Your question or situation')}</label><span id="save-status">${paused?'Saving paused':'Saved in this browser'}</span></div><textarea id="problem" data-problem rows="1" maxlength="20000">${e(kit.w().problem)}</textarea></section>${config.render(kit.w(),kit)}<p class="local-note">Fictional starting example. Your material stays in this browser; export a copy to keep it.</p>`;destroy=attachCardDrag({root,onDrop:({itemId,dropId})=>config.drop?.(itemId,dropId,kit)});config.afterRender?.(kit);requestAnimationFrame(()=>resize());}
  function open(html,title){if(!dialog.open)dialogOrigin={id:document.activeElement?.id,data:document.activeElement?.dataset?.action?{...document.activeElement.dataset}:null};dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${html}`;dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>resize(dialog));}
  function workspaces(){open(`<p>New work and imports keep your existing workspaces.</p><div class="toolbar"><button class="primary" data-action="new" data-example="blank">+ My own material</button><button data-action="new" data-example="example">New example</button><button data-action="fork-workspace">Duplicate this workspace</button></div><div class="workspace-list">${[...h.present.workspaces].reverse().map(w=>`<button data-action="switch" data-id="${e(w.id)}"><strong>${e(w.problem||'Untitled')}</strong><span>${w.id===h.present.activeId?'Open':'→'}</span></button>`).join('')}</div><button data-action="import">Import editable JSON ↑</button>`,'My work');}
  document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='undo'){h=undo(h);save();render();toast('Last change undone.');}else if(a==='workspaces')workspaces();else if(a==='new'||a==='fork-workspace'){dialog.close();act({type:a,id:uid(),example:b.dataset.example});}else if(a==='switch'){dialog.close();act({type:'switch',id:b.dataset.id},{checkpoint:false});}else if(a==='close')dialog.close();else if(a==='export')open('<p>Export this workspace with its alternatives and reasoning.</p><div class="toolbar"><button class="primary" data-action="markdown">Markdown ↓</button><button data-action="json">Editable JSON ↓</button></div>','Export work');else if(a==='markdown'||a==='json'){downloadText(`${config.route}.${a==='json'?'json':'md'}`,a==='json'?portable(kit.w(),config.route,config.validate):config.markdown(kit.w()),a==='json'?'application/json':'text/markdown;charset=utf-8');dialog.close();}else if(a==='import')document.querySelector('#import-file').click();else if(a==='recover'){if(recovery)downloadText(`${config.route}-recovery.json`,recovery,'application/json');recovery=null;paused=false;save();render();}else if(config.handle)config.handle(a,b.dataset,kit);});
  function edited(el){if(el.hasAttribute('data-problem'))act({type:'problem',value:el.value},{repaint:false,group:'problem'});else if(el.dataset.field)act({type:'edit',collection:el.dataset.collection,item:el.dataset.item,field:el.dataset.field,value:el.value},{repaint:false,group:el.id});resize(el.parentElement);}
  document.addEventListener('input',event=>{if(event.target.matches('textarea,input[data-field]'))edited(event.target);});document.addEventListener('change',event=>{if(event.target.matches('select[data-field]')){edited(event.target);if(!dialog.open)render();}});document.addEventListener('focusout',()=>{h.group=null;});dialog.addEventListener('close',()=>{if(dialog.open)return;render();(dialogOrigin?.id?document.getElementById(dialogOrigin.id):control(dialogOrigin?.data))?.focus({preventScroll:true});dialogOrigin=null;});
  document.querySelector('#import-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>8000000)throw Error('Choose a file under 8 MB.');const raw=await file.text(),w=config.parseImport?config.parseImport(raw):parse(raw,config.route,config.validate);dialog.close();if(act({type:'import',id:uid(),workspace:w}))toast('Imported as a new workspace. Previous work is kept.');}catch(error){toast(error.message);}event.target.value='';});
  window.addEventListener('pagehide',()=>save(true));window.addEventListener('storage',event=>{if(event.key===key&&event.newValue!==JSON.stringify(h.present)){clearTimeout(timer);paused=true;render();}});render();return kit;
}
